library(shiny)
library(ggplot2)
library(tidyverse)
library(patchwork)

ui <- navbarPage(

  "Bristol Mixed Pass Tracker",

  tabPanel(
    "Tracker",

    tags$head(tags$style(HTML("
      body { background-color: #111; color: white; }

      .big-btn {
        flex: 1;
        margin: 2px;
        height: 80px;
        font-size: 20px;
        font-weight: bold;
        border-radius: 14px;
      }

      .section-title {
        font-size: 22px;
        margin-top: 14px;
        color: white;
      }

      .holder-box {
        padding: 12px;
        border-radius: 12px;
        text-align: center;
        font-size: 20px;
        font-weight: bold;
        margin-bottom: 10px;
        border: 2px solid white;
        background-color: rgba(255,255,255,0.1);
      }

      #carrier_m { background-color: white; color: #971f07; }
      #turnover_m { background-color: white; color: #0aaecf; }
      #goal_m { background-color: white; color: #cf8e0a; }

      #carrier_f { background-color: #971f07; color: white; }
      #turnover_f { background-color: #0aaecf; color: white; }
      #goal_f { background-color: #cf8e0a; color: white; }

      .stat-box {
        padding: 10px;
        border-radius: 10px;
        margin-bottom: 8px;
        text-align: center;
        font-size: 16px;
        font-weight: bold;
        border: 2px solid white;
        background-color: rgba(255,255,255,0.1);
      }

      /* Correction du fond noir des graphiques */
      .shiny-plot-output { background-color: black !important; }
      .tab-content { background-color: #111; }
    "))),

    div(class="section-title", "Current Disc Holder"),
    div(class="holder-box", textOutput("current_holder")),

    div(class="section-title", "Disk Carrier"),
    div(style="display:flex;",
        actionButton("carrier_m","M",class="big-btn"),
        actionButton("carrier_f","F",class="big-btn")
    ),

    div(class="section-title", "Turnover Target"),
    div(style="display:flex;",
        actionButton("turnover_m","M",class="big-btn"),
        actionButton("turnover_f","F",class="big-btn")
    ),

    div(class="section-title", "Goal Scorer"),
    div(style="display:flex;",
        actionButton("goal_m","M",class="big-btn"),
        actionButton("goal_f","F",class="big-btn")
    ),

    br(),

    div(class="section-title", "Live Stats"),

    fluidRow(
      column(6, div(class="stat-box", textOutput("count_mm"))),
      column(6, div(class="stat-box", textOutput("count_mf")))
    ),

    fluidRow(
      column(6, div(class="stat-box", textOutput("count_fm"))),
      column(6, div(class="stat-box", textOutput("count_ff")))
    ),

    fluidRow(
      column(6, div(class="stat-box", textOutput("count_turnovers"))),
      column(6, div(class="stat-box", textOutput("count_assists")))
    ),

    br(),

    actionButton("undo","Undo Last Action",class="btn-danger big-btn"),
    br(),
    actionButton("download","Download Game Data",class="btn-primary big-btn"),
    br(), br(),
    actionButton("reset","Reset All",class="btn-warning big-btn")
  ),

  tabPanel(
    "Graphs",
    br(),
    # Intégration des trois nouvelles sections de graphiques
    fluidRow(
      column(12, 
             h3("1. Completions, Disc Touches & Goals", style="color:white;"),
             plotOutput("plot_completions_touches_goals", height = "350px"),
             br(), hr(), br(),

             h3("2. Completions per Pass Type", style="color:white;"),
             plotOutput("plot_completions_per_type", height = "500px"),
             br(), hr(), br(),

             h3("3. Pass Type per Outcome", style="color:white;"),
             plotOutput("plot_type_per_outcome", height = "500px")
      )
    )
  )
)

server <- function(input, output, session) {

  rv <- reactiveValues(
    data = data.frame(Timestamp=character(),
                      From=character(),
                      To=character(),
                      Outcome=character(),
                      stringsAsFactors=FALSE),
    current_from = NULL,
    history = list()
  )

  output$current_holder <- renderText({
    if(is.null(rv$current_from)) {
      "None (Start of possession)"
    } else {
      paste("Current:", rv$current_from)
    }
  })

  log_pass <- function(to, outcome) {
    rv$history <- c(rv$history, list(list(last_from = rv$current_from, last_data = rv$data)))
    new_row <- data.frame(
      Timestamp = as.character(Sys.time()),
      From = rv$current_from,
      To = to,
      Outcome = outcome,
      stringsAsFactors = FALSE
    )
    rv$data <- rbind(rv$data, new_row)
    rv$current_from <- if(outcome == "Completed") to else NULL
  }

  observeEvent(input$carrier_m, {
    rv$history <- c(rv$history, list(list(last_from = rv$current_from, last_data = rv$data)))
    if(is.null(rv$current_from)) { rv$current_from <- "M" } else { log_pass("M","Completed"); rv$current_from <- "M" }
  })

  observeEvent(input$carrier_f, {
    rv$history <- c(rv$history, list(list(last_from = rv$current_from, last_data = rv$data)))
    if(is.null(rv$current_from)) { rv$current_from <- "F" } else { log_pass("F","Completed"); rv$current_from <- "F" }
  })

  observeEvent(input$turnover_m, { if(!is.null(rv$current_from)) log_pass("M","Turnover") })
  observeEvent(input$turnover_f, { if(!is.null(rv$current_from)) log_pass("F","Turnover") })
  observeEvent(input$goal_m, { if(!is.null(rv$current_from)) log_pass("M","Assist") })
  observeEvent(input$goal_f, { if(!is.null(rv$current_from)) log_pass("F","Assist") })

  observeEvent(input$undo, {
    if(length(rv$history) > 0) {
      last <- rv$history[[length(rv$history)]]; rv$history <- rv$history[-length(rv$history)]
      rv$data <- last$last_data; rv$current_from <- last$last_from
    }
  })

  observeEvent(input$reset, {
    rv$data <- data.frame(Timestamp=character(), From=character(), To=character(), Outcome=character(), stringsAsFactors=FALSE)
    rv$current_from <- NULL; rv$history <- list()
  })

  output$count_mm <- renderText({ paste("M → M:", sum(rv$data$From=="M" & rv$data$To=="M" & rv$data$Outcome=="Completed")) })
  output$count_mf <- renderText({ paste("M → F:", sum(rv$data$From=="M" & rv$data$To=="F" & rv$data$Outcome=="Completed")) })
  output$count_fm <- renderText({ paste("F → M:", sum(rv$data$From=="F" & rv$data$To=="M" & rv$data$Outcome=="Completed")) })
  output$count_ff <- renderText({ paste("F → F:", sum(rv$data$From=="F" & rv$data$To=="F" & rv$data$Outcome=="Completed")) })
  output$count_turnovers <- renderText({ paste("Turnovers:", sum(rv$data$Outcome=="Turnover")) })
  output$count_assists <- renderText({ paste("Assists:", sum(rv$data$Outcome=="Assist")) })

  observeEvent(input$download, {
    csv <- paste(capture.output(write.csv(rv$data, row.names=FALSE)), collapse="\n")
    filename <- paste0("ultimate_pass_data_", format(Sys.time(), "%Y-%m-%d_%H-%M-%S"), ".csv")
    session$sendCustomMessage("downloadData", list(csv=csv, filename=filename))
  })

  # --- CONFIGURATION DU THÈME POUR TOUS LES GRAPHES ---
  black_theme <- theme_void() + theme(
    plot.background = element_rect(fill = "black", color = NA),
    panel.background = element_rect(fill = "black", color = NA),
    legend.background = element_rect(fill = "black", color = NA),
    legend.box.background = element_rect(fill = "black", color = NA),
    legend.key = element_rect(fill = "black", color = NA),
    legend.text = element_text(color = "white"),
    legend.title = element_text(color = "white"),
    plot.title = element_text(color = "white", size = 14, face = "bold", hjust = 0.5)
  )

  # --- GRAPH 1 : Completions, disk touches and goals ---
  output$plot_completions_touches_goals <- renderPlot({
    stats <- rv$data
    if(nrow(stats) == 0) return(NULL)

    # Completions
    totcompl <- length(which(stats$Outcome != "Turnover"))
    totturn <- length(which(stats$Outcome == "Turnover"))
    totpasses <- totcompl + totturn

    allcompl <- ggplot() + black_theme
    if(totpasses > 0){
      df1 <- data.frame(Outcome = c("Completed", "Turnover"), Percentage = c(totcompl*100/totpasses, totturn*100/totpasses))
      allcompl <- ggplot(df1, aes(x="", y=Percentage, fill=Outcome)) + 
        geom_bar(stat="identity", width = 1) + scale_fill_manual(values=c("aquamarine3", "indianred3")) + coord_polar("y") +
        geom_text(aes(label = paste0(round(Percentage, 1), "%")), position = position_stack(vjust = 0.5), color = "white", fontface = "bold", size = 4) +
        labs(title=paste0("Pass attempts = ", totpasses)) + black_theme
    }

    # Touches
    totF <- length(which(stats$From == "F"))
    totM <- length(which(stats$From == "M"))
    totpasses_t <- totF + totM

    alltouches <- ggplot() + black_theme
    if(totpasses_t > 0){
      df2 <- data.frame(Gender = c("F", "M"), Percentage = c(totF*100/totpasses_t, totM*100/totpasses_t))
      alltouches <- ggplot(df2, aes(x="", y=Percentage, fill=Gender)) + 
        geom_bar(stat="identity", width = 1) + scale_fill_manual(values=c("gold2", "darkorange3")) + coord_polar("y") +
        geom_text(aes(label = paste0(round(Percentage, 1), "%")), position = position_stack(vjust = 0.5), color = "white", fontface = "bold", size = 4) +
        labs(title=paste0("Disc Touches = ", totpasses_t)) + black_theme
    }

    # Goals
    totF_g <- length(which(stats$To == "F" & stats$Outcome == "Assist"))
    totM_g <- length(which(stats$To == "M" & stats$Outcome == "Assist"))
    totpasses_g <- totF_g + totM_g

    allgoals <- ggplot() + black_theme
    if(totpasses_g > 0){
      df3 <- data.frame(Gender = c("F", "M"), Percentage = c(totF_g*100/totpasses_g, totM_g*100/totpasses_g))
      allgoals <- ggplot(df3, aes(x="", y=Percentage, fill=Gender)) + 
        geom_bar(stat="identity", width = 1) + scale_fill_manual(values=c("gold2", "darkorange3")) + coord_polar("y") +
        geom_text(aes(label = paste0(round(Percentage, 1), "%")), position = position_stack(vjust = 0.5), color = "white", fontface = "bold", size = 4) +
        labs(title=paste0("Goals = ", totpasses_g)) + black_theme
    }

    allcompl | alltouches | allgoals & black_theme
  }, bg = "black")

  # --- GRAPH 2 : Completions per pass type ---
  output$plot_completions_per_type <- renderPlot({
    stats <- rv$data
    if(nrow(stats) == 0) return(NULL)
    stats$passtype = paste0(stats$From, stats$To)

    make_sub_pie <- function(type_str) {
      sub_data <- stats[which(stats$passtype == type_str),]
      totcompl <- length(which(sub_data$Outcome != "Turnover"))
      totturn <- length(which(sub_data$Outcome == "Turnover"))
      tot <- totcompl + totturn

      if(tot == 0) return(ggplot() + labs(title=paste(type_str, "(No data)")) + black_theme)

      df <- data.frame(Outcome = c("Completed", "Turnover"), Percentage = c(totcompl*100/tot, totturn*100/tot))
      ggplot(df, aes(x="", y=Percentage, fill=Outcome)) + 
        geom_bar(stat="identity", width = 1) + scale_fill_manual(values=c("aquamarine3", "indianred3")) + coord_polar("y") +
        geom_text(aes(label = paste0(round(Percentage, 1), "%")), position = position_stack(vjust = 0.5), color = "white", fontface = "bold", size = 4) +
        labs(title=type_str) + black_theme
    }

    (make_sub_pie("MM") | make_sub_pie("MF")) / (make_sub_pie("FM") | make_sub_pie("FF")) & black_theme
  }, bg = "black")

  # --- GRAPH 3 : Pass type per outcome ---
  output$plot_type_per_outcome <- renderPlot({
    stats <- rv$data
    if(nrow(stats) == 0) return(NULL)
    stats$passtype = paste0(stats$From, stats$To)

    # Filtre les lignes vides ou incomplètes (ex: From ou To vide au début de l'action)
    stats <- stats[stats$passtype %in% c("MM","MF","FM","FF"), ]
    if(nrow(stats) == 0) return(NULL)

    colors_mix <- c("MM" = "darkorange3", "MF" = "darkslategray", "FM" = "cyan4", "FF" = "gold2")

    make_mix_pie <- function(df_subset, title_str) {
      if(nrow(df_subset) == 0) return(ggplot() + labs(title=paste(title_str, "(No data)")) + black_theme)
      df_mix <- as.data.frame(table(df_subset$passtype))
      names(df_mix) <- c("Passtype","Occurence")
      df_mix$Percentage <- df_mix$Occurence / sum(df_mix$Occurence) * 100

      ggplot(df_mix, aes(x="", y=Percentage, fill=Passtype)) + 
        geom_bar(stat="identity", width = 1) + scale_fill_manual(values = colors_mix) + coord_polar("y") +
        geom_text(aes(label = paste0(round(Percentage, 1), "%")), position = position_stack(vjust = 0.5), color = "white", fontface = "bold", size = 4) +
        labs(title=title_str) + black_theme
    }

    all_mix <- make_mix_pie(stats, "Total attempts")
    compl   <- make_mix_pie(stats[which(stats$Outcome != "Turnover"),], "Completions")
    assist  <- make_mix_pie(stats[which(stats$Outcome == "Assist"),], "Assists")
    turn    <- make_mix_pie(stats[which(stats$Outcome == "Turnover"),], "Turnovers")

    (all_mix | compl) / (assist | turn) & black_theme
  }, bg = "black")
}

shinyApp(ui, server)
